// HSV CONVERSION

// from https://www.shadertoy.com/view/wt23Rt
//Source: https://gist.github.com/yiwenl/745bfea7f04c456e0101
vec3 rgb2hsv(vec3 c) {
	float cMax=max(max(c.r,c.g),c.b),
	      cMin=min(min(c.r,c.g),c.b),
	      delta=cMax-cMin;
	vec3 hsv=vec3(0.,0.,cMax);
	if(cMax>cMin){
		hsv.y=delta/cMax;
		if(c.r==cMax){
			hsv.x=(c.g-c.b)/delta;
		}else if(c.g==cMax){
			hsv.x=2.+(c.b-c.r)/delta;
		}else{
			hsv.x=4.+(c.r-c.g)/delta;
		}
		hsv.x=fract(hsv.x/6.);
	}
	return hsv;
}

void mainImage( out vec4 fragColor, in vec2 fc )
{
    vec2 uv = fc/iResolution.xy;
    vec3 c = texture(iChannel0, uv).rgb;
    vec3 hsv = rgb2hsv(c);
    fragColor.rgb = hsv;
}

// VALUE MASK

void mainImage( out vec4 fragColor, in vec2 fc )
{

#ifdef BLUR_MASK
    float v = 0.f;
    float tw = 0.f;
    float w = 1.f;
    for(int y = -blurRad; y <= blurRad; y++) 
    for(int x = -blurRad; x <= blurRad; x++) 
    {
        vec2 o = vec2(x,y);
        float w = gaussFactor * exp(dot(o,o) * gaussExpFactor);
        v += w * texelFetch(iChannel0, ivec2(fc+o), 0).z;
        tw += w;
    }
    v /= tw;
#else
    float v = texelFetch(iChannel0, ivec2(fc), 0).z;
#endif
    // threshold
    float tMin = 0.125f;
    float tMax = 0.65f;

    vec2 dir = LineDir(iTime);
    float k = dot(fc, dir.yx*vec2(1,-1)); // position orthogonally to line direction <==> which line are we on?
    k = floor(k * 0.5f);
    float r = hash11(k);
    tMin += r * 0.1f;
    tMax += r * 0.1f;
    v = v > tMin && v < tMax ? 1.f : 0.f;

    fragColor.rgb = vec3(v);
}

// "SORTING" STEP
// There is no actual sorting, this just gets the [min, max] value range in the masked area along the current direction
// and then draws a gradient from 'min' to 'max' over those pixels

// is pixel in mask / should it be "sorted" 
bool Valid(vec2 p)
{
    return texture(iChannel0, p).r > 0.5f; // mask values are 0 or 1, but we sample linearily, so 0.5...
}

void mainImage( out vec4 fragColor, in vec2 fc )
{
    vec2 uv = fc / iResolution.xy;
    // Check if masked => return if not in region to be sorted
    if(!Valid(uv)) {
        fragColor.rgb = texelFetch(iChannel1, ivec2(fc), 0).rgb;
        return;
    }

    // sorting direction and step size
    vec2 dir = LineDir(iTime);
    vec2 uvStep = dir / iResolution.xy;

    // "SORTING"
    // we march along the pixels before (along direction)
    // aswell as along the pixels after the current one
    // => get min & max values so we know how intense to shade the gradient
    float minVal = 1000.f;
    float maxVal = -1.f;

    // sample before
    float avgBefore = 0.f;
    vec2 uvBefore = uv; 
    int numStepsBefore = 0;
    for(; all(lessThanEqual(abs(uvBefore-0.5f), vec2(0.5f))) && numStepsBefore < 3000; uvBefore -= uvStep) {
        if(!Valid(uvBefore)) break;
        float v = texture(iChannel1, uvBefore).z;
        avgBefore += v;
        minVal = min(minVal, v);
        maxVal = max(maxVal, v);
        numStepsBefore++;
    }
    avgBefore /= float(numStepsBefore);

    // sample after
    float avgAfter = 0.f;
    vec2 uvAfter = uv;
    int numStepsAfter = 0;
    for(; all(lessThanEqual(abs(uvAfter-0.5f), vec2(0.5f))) && numStepsAfter < 3000; uvAfter += uvStep) {
        if(!Valid(uvAfter)) break;
        float v = texture(iChannel1, uvAfter).z;
        avgAfter += v;
        minVal = min(minVal, v);
        maxVal = max(maxVal, v);
        numStepsAfter++;
    }
    avgAfter /= float(numStepsAfter);

    float a = length(uv-uvBefore) / length(uvAfter-uvBefore);
#ifdef FLIP_VALUES
    // OPTIONALLY: Flip gradient to better match original direction/value distribution 
    // per default we shade min->max over pixel range.
    // But if the average values are higher before our pixel than after it, then flipping the gradient
    //     (shading max->min) might be a better fit
    // I like the sharpness which the "wrongfully" flipped values created, so this is off by default
    if(avgBefore > avgAfter) a = 1.f - a;
#endif

    // Shade Gradient from min to max over range
    float ownVal = mix(minVal, maxVal, a);
    fragColor.rgb = texelFetch(iChannel1, ivec2(fc), 0).rgb;
    fragColor.b = ownVal;
}

// HSV TO RGB

// from https://www.shadertoy.com/view/wt23Rt
//Sources: https://gist.github.com/yiwenl/745bfea7f04c456e0101, https://gist.github.com/sugi-cho/6a01cae436acddd72bdf
vec3 hsv2rgb(vec3 c){
	vec4 K=vec4(1.,2./3.,1./3.,3.);
	return c.z*mix(K.xxx,clamp(abs(fract(c.x+K.xyz)*6.-K.w)-K.x, 0.f, 1.f),c.y);
}



void mainImage( out vec4 fragColor, in vec2 fc )
{
    vec3 hsv = texelFetch(iChannel0, ivec2(fc), 0).rgb;
    fragColor.rgb = vec3(hsv.z); //hsv2rgb(hsv);
}

#define BLUR_MASK
// Uncomment to flip gradient if that matches value distribution better
//#define FLIP_VALUES

const float PI = 3.1415927f;
const int blurRad = 4;
const float gaussSigma = 4.f;
const float gaussFactor = 1.f / sqrt(2.f * PI * gaussSigma * gaussSigma);
const float gaussExpFactor = -1.f / (2.f * gaussSigma * gaussSigma);

vec2 LineDir(float t)
{
    float ang = -t * 0.25f;
    return normalize(vec2(cos(ang), sin(ang)));
}


// from nojima - https://www.shadertoy.com/view/ttc3zr
uint murmurHash11(uint src) {
    const uint M = 0x5bd1e995u;
    uint h = 1190494759u;
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

// 1 output, 1 input
float hash11(float src) {
    uint h = murmurHash11(floatBitsToUint(src));
    return uintBitsToFloat(h & 0x007fffffu | 0x3f800000u) - 1.0;
}
